  interface PluginState {
    'task-pane': {
      list: TaskPaneList
      agentList: StateFamily<TaskPaneList>
      agentIds: readonly string[]
      expanded: readonly string[]
      activity: TaskPaneActivity
      agentActivity: readonly TaskPaneAgentActivity[]
      ready: { root: string }
